import{_ as e,o as d,c as o,a5 as r}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Test Specification — FR 3.10.14: Export Report File PDF","description":"","frontmatter":{},"headers":[],"relativePath":"feature/admin-management/3-10-12-export-report-file-pdf/test.md","filePath":"feature/admin-management/3-10-12-export-report-file-pdf/test.md"}'),n={name:"feature/admin-management/3-10-12-export-report-file-pdf/test.md"};function l(a,t,i,s,c,g){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="test-specification-—-fr-3-10-14-export-report-file-pdf" tabindex="-1">Test Specification — FR 3.10.14: Export Report File PDF <a class="header-anchor" href="#test-specification-—-fr-3-10-14-export-report-file-pdf" aria-label="Permalink to &quot;Test Specification — FR 3.10.14: Export Report File PDF&quot;">​</a></h1><p>&gt; Note: This specification maps to official <strong>FR 3.10.14 — Export Report File PDF</strong> in the 141 Atomic CRUD FR baseline (canonical folder: <code>../3-10-14-export-report-file-pdf/</code>).</p><h2 id="_1-traceability-execution-summary" tabindex="-1">1. Traceability &amp; Execution Summary <a class="header-anchor" href="#_1-traceability-execution-summary" aria-label="Permalink to &quot;1. Traceability &amp; Execution Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR ID</strong></td><td style="text-align:left;"><code>FR 3.10.14</code></td></tr><tr><td style="text-align:left;"><strong>Function Name</strong></td><td style="text-align:left;">Export Report File PDF</td></tr><tr><td style="text-align:left;"><strong>Functional Domain</strong></td><td style="text-align:left;">Admin</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Admin</code></td></tr><tr><td style="text-align:left;"><strong>Target Class &amp; Method</strong></td><td style="text-align:left;"><code>AdminReportService.create()</code> (40 LOC)</td></tr><tr><td style="text-align:left;"><strong>Unit Test File</strong></td><td style="text-align:left;"><code>brandhub-business-service/src/test/java/com/brandhub/business/service/admin/AdminReportServiceTest.java</code></td></tr><tr><td style="text-align:left;"><strong>Code &amp; Test Author</strong></td><td style="text-align:left;">Ân</td></tr><tr><td style="text-align:left;"><strong>Test Requirement</strong></td><td style="text-align:left;">Render a REVENUE, USER, or PLATFORM PDF report for a date range, store with 24h SHA-256 token link, or reject if NO_DATA_IN_RANGE</td></tr><tr><td style="text-align:left;"><strong>Preconditions</strong></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role</td></tr><tr><td style="text-align:left;"><strong>Overall Status</strong></td><td style="text-align:left;"><strong>Passed (100%)</strong></td></tr><tr><td style="text-align:left;"><strong>Test Case Breakdown</strong></td><td style="text-align:left;"><strong>Total: 16</strong> (<code>Passed</code>: 16, <code>Failed</code>: 0, <code>Untested</code>: 0) — <code>Normal (N)</code>: 8, <code>Boundary (B)</code>: 3, <code>Abnormal (A)</code>: 5</td></tr></tbody></table><hr><h2 id="_2-unit-test-case-matrix-utcid01–utcid16" tabindex="-1">2. Unit Test Case Matrix (<code>UTCID01</code>–<code>UTCID16</code>) <a class="header-anchor" href="#_2-unit-test-case-matrix-utcid01–utcid16" aria-label="Permalink to &quot;2. Unit Test Case Matrix (`UTCID01`–`UTCID16`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Test Case ID</th><th style="text-align:center;">Type</th><th style="text-align:left;">Preconditions</th><th style="text-align:left;">Test Inputs</th><th style="text-align:left;">Expected Return / Exception</th><th style="text-align:left;">Log Message</th><th style="text-align:center;">Status</th></tr></thead><tbody><tr><td style="text-align:left;"><code>UTCID01</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Selected period has non-zero rows for reportType (REVENUE, USER, or PLATFORM)</td><td style="text-align:left;"><code>request</code> = <code>AdminReportRequest(REVENUE, from, to, &#39;Asia/Ho_Chi_Minh&#39;)</code>, <code>downloadCall</code> = <code>create(actor, request)</code></td><td style="text-align:left;">200 OK - create() renders REVENUE PDF via AdminReportPdf and returns AdminReportExportResponse</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID02</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Selected period has non-zero rows for reportType (REVENUE, USER, or PLATFORM)</td><td style="text-align:left;"><code>request</code> = <code>AdminReportRequest(REVENUE, from, to, &#39;Asia/Ho_Chi_Minh&#39;)</code>, <code>downloadCall</code> = <code>download(actor, id, validToken)</code></td><td style="text-align:left;">200 OK - create() renders USER PDF with user status, role, and strike summary rows</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID03</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Selected period has non-zero rows for reportType (REVENUE, USER, or PLATFORM)</td><td style="text-align:left;"><code>request</code> = <code>AdminReportRequest(USER, from, to, &#39;UTC&#39;)</code>, <code>downloadCall</code> = <code>create(actor, request)</code></td><td style="text-align:left;">200 OK - create() renders PLATFORM PDF with platform-wide KPI and registration metrics</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID04</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Selected period has non-zero rows for reportType (REVENUE, USER, or PLATFORM)</td><td style="text-align:left;"><code>request</code> = <code>AdminReportRequest(USER, from, to, &#39;UTC&#39;)</code>, <code>downloadCall</code> = <code>download(actor, id, validToken)</code></td><td style="text-align:left;">200 OK - Only SHA-256 hash of download token is stored in admin_report_exports (24h expiresAt)</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID05</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Exported PDF is stored in admin_report_exports with SHA-256 token hash and 24h TTL</td><td style="text-align:left;"><code>request</code> = <code>AdminReportRequest(REVENUE, from, to, &#39;Asia/Ho_Chi_Minh&#39;)</code>, <code>downloadCall</code> = <code>purgeExpired() TTL cleanup</code></td><td style="text-align:left;">200 OK - download(actor, id, validToken) verifies constant-time SHA-256 and returns Download(fileName, pdfBytes)</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID06</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Exported PDF is stored in admin_report_exports with SHA-256 token hash and 24h TTL</td><td style="text-align:left;"><code>request</code> = <code>AdminReportRequest(USER, from, to, &#39;UTC&#39;)</code>, <code>downloadCall</code> = <code>purgeExpired() TTL cleanup</code></td><td style="text-align:left;">200 OK - AdminAudit records EXPORT on ADMIN_REPORT with reportType, rowCount, fileName, expiresAt</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID07</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Selected period has non-zero rows for reportType (REVENUE, USER, or PLATFORM)</td><td style="text-align:left;"><code>request</code> = <code>AdminReportRequest(REVENUE, from, to, &#39;Asia/Ho_Chi_Minh&#39;)</code>, <code>downloadCall</code> = <code>create(actor, request)</code></td><td style="text-align:left;">200 OK - purgeExpired() sets content=null on expired rows while keeping metadata audit trail</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID08</code></td><td style="text-align:center;"><code>N</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Selected period has non-zero rows for reportType (REVENUE, USER, or PLATFORM)</td><td style="text-align:left;"><code>request</code> = <code>AdminReportRequest(REVENUE, from, to, &#39;Asia/Ho_Chi_Minh&#39;)</code>, <code>downloadCall</code> = <code>download(actor, id, validToken)</code></td><td style="text-align:left;">200 OK - Blank timezone defaults to &#39;Asia/Ho_Chi_Minh&#39; and fileName formatted as BrandHub_Report_&lt;type&gt;_&lt;dates&gt;.pdf</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID09</code></td><td style="text-align:center;"><code>B</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Period is a single day (from == to) with 1 row or timezone is blank (defaults to Asia/Ho_Chi_Minh)</td><td style="text-align:left;"><code>request</code> = <code>AdminReportRequest(PLATFORM, from, to, null)</code>, <code>downloadCall</code> = <code>single-day boundary report (1 row)</code></td><td style="text-align:left;">200 OK - Single-day period (from == to) with 1 data row exports valid PDF at boundary</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID10</code></td><td style="text-align:center;"><code>B</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Period is a single day (from == to) with 1 row or timezone is blank (defaults to Asia/Ho_Chi_Minh)</td><td style="text-align:left;"><code>request</code> = <code>AdminReportRequest(PLATFORM, from, to, null)</code>, <code>downloadCall</code> = <code>single-day boundary report (1 row)</code></td><td style="text-align:left;">200 OK - Large dataset capped at MAX_ROWS=5000 rows in PDF table section</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID11</code></td><td style="text-align:center;"><code>B</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Selected period has non-zero rows for reportType (REVENUE, USER, or PLATFORM)</td><td style="text-align:left;"><code>request</code> = <code>AdminReportRequest(REVENUE, from, to, &#39;Asia/Ho_Chi_Minh&#39;)</code>, <code>downloadCall</code> = <code>purgeExpired() TTL cleanup</code></td><td style="text-align:left;">200 OK - Download right before 24-hour expiresAt boundary returns PDF bytes</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID12</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Selected period has 0 rows (NO_DATA_IN_RANGE), token is invalid, or 24h download link expired</td><td style="text-align:left;"><code>request</code> = <code>empty-data date range (0 rows)</code>, <code>downloadCall</code> = <code>create(actor, request)</code></td><td style="text-align:left;">NO_DATA_IN_RANGE - 400 Selected period has 0 rows (raises error instead of empty PDF)</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID13</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Selected period has 0 rows (NO_DATA_IN_RANGE), token is invalid, or 24h download link expired</td><td style="text-align:left;"><code>request</code> = <code>invalid date range (from &gt; to)</code>, <code>downloadCall</code> = <code>create(actor, request)</code></td><td style="text-align:left;">INVALID_REQUEST - 400 Start date is after end date or timezone is invalid</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID14</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Caller does not have ADMIN system role</td><td style="text-align:left;"><code>request</code> = <code>AdminReportRequest(REVENUE, from, to, &#39;Asia/Ho_Chi_Minh&#39;)</code>, <code>downloadCall</code> = <code>create(actor, request)</code></td><td style="text-align:left;">FORBIDDEN - 403 Caller does not have ADMIN system role</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID15</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Selected period has non-zero rows for reportType (REVENUE, USER, or PLATFORM)</td><td style="text-align:left;"><code>request</code> = <code>empty-data date range (0 rows)</code>, <code>downloadCall</code> = <code>download with wrong/null token</code></td><td style="text-align:left;">REPORT_NOT_FOUND - 404 Report ID does not exist or download token SHA-256 mismatches</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr><tr><td style="text-align:left;"><code>UTCID16</code></td><td style="text-align:center;"><code>A</code></td><td style="text-align:left;">Can connect with server; Caller has ADMIN system role (AdminAccountService.requireAdmin); Selected period has non-zero rows for reportType (REVENUE, USER, or PLATFORM)</td><td style="text-align:left;"><code>request</code> = <code>invalid date range (from &gt; to)</code>, <code>downloadCall</code> = <code>download after 24h expiry or after purgeExpired</code></td><td style="text-align:left;">REPORT_LINK_EXPIRED - 410 Report download link has expired (&gt;24h) or content was purged</td><td style="text-align:left;">—</td><td style="text-align:center;"><strong>Passed</strong></td></tr></tbody></table><hr><h2 id="_3-synchronization-verification-notes" tabindex="-1">3. Synchronization &amp; Verification Notes <a class="header-anchor" href="#_3-synchronization-verification-notes" aria-label="Permalink to &quot;3. Synchronization &amp; Verification Notes&quot;">​</a></h2><ul><li>Synchronized 1-to-1 with <a href="./../../../../brandhub-final_report/report5/Report5_Unit Test.xls.html"><code>Report5_Unit Test.xls</code></a> sheet <code>FR3.10.14</code>, <a href="./../../../../brandhub-final_report/report5/Report5_Test Report.xlsx.html"><code>Report5_Test Report.xlsx</code></a>, and <a href="./../../../../brandhub-final_report/report5/Report5_Test Documentation.docx.html"><code>Report5_Test Documentation.docx</code></a>.</li><li>Role names strictly follow the 6 canonical roles (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>).</li></ul><hr><h2 id="_4-feature-acceptance-integration-verification" tabindex="-1">4. Feature Acceptance &amp; Integration Verification <a class="header-anchor" href="#_4-feature-acceptance-integration-verification" aria-label="Permalink to &quot;4. Feature Acceptance &amp; Integration Verification&quot;">​</a></h2><h1 id="test-—-3-10-12-export-report-file-pdf" tabindex="-1">Test — 3-10-12-export-report-file-pdf <a class="header-anchor" href="#test-—-3-10-12-export-report-file-pdf" aria-label="Permalink to &quot;Test — 3-10-12-export-report-file-pdf&quot;">​</a></h1><p>Các kỳ vọng chi tiết: Acceptance Criteria/Edge Cases trong <a href="./spec.html">spec</a> và mục 6 của <a href="./../plan.html">plan kỹ thuật</a>.</p><ul><li><p>[x] No data MSG122: không tạo file, không thêm dòng export.</p></li><li><p>[x] link 24h: <code>expiresAt</code> = lúc tạo + 24 giờ; job xóa nội dung file khi hết hạn, metadata giữ làm audit; tải sau hạn → 410.</p></li><li><p>[x] ADMIN download: tải cần cả quyền ADMIN hiện tại và token; sai token → 404; USER → 403.</p></li><li><p>[x] parity với dashboard: báo cáo doanh thu dùng chung <code>AdminRevenueService</code> với màn Doanh thu.</p></li><li><p>[x] A4/Vietnamese/overflow: font Liberation Sans nhúng; trích văn bản PDF ra đúng chữ có dấu; bảng tự xuống dòng và lặp header khi sang trang.</p></li><li><p>[x] VI/EN và light/dark cho modal/trang xuất.</p></li><li><p>[ ] Báo cáo moderation: chờ FR 3.10.4.</p></li><li><p>[x] Chưa đăng nhập 401; USER gọi Admin 403 (<code>AdminSecurityTest</code>).</p></li><li><p>[x] Lỗi server không báo thành công; nút tải bị khóa khi đang tạo.</p></li><li><p>[x] PDF không chứa passwordHash/otpCode/totpSecret; audit EXPORT lưu loại, kỳ, múi giờ, asOf, số dòng, tên file, hạn tải.</p></li></ul><h2 id="ket-qua" tabindex="-1">Kết quả <a class="header-anchor" href="#ket-qua" aria-label="Permalink to &quot;Kết quả&quot;">​</a></h2><p>Bằng chứng chung (2026-10-04):</p><ul><li><code>AdminFinanceDatabaseTest</code> (PostgreSQL 17, DB <code>brandhub_admin_20261001_test</code>, clock cố định 2030 để không đụng dữ liệu khác): 4/4 pass. <code>AdminReportPeriodTest</code> 3/3, <code>AdminSecurityTest</code> 11/11 pass.</li><li>Playwright <code>tests/e2e/admin/finance.spec.ts</code> 5/5 pass (API mock); toàn bộ <code>tests/e2e/admin/{overview,accounts,finance}</code> 22/22.</li><li><code>npx tsc</code>, ESLint các file đổi và <code>npm run build</code> pass.</li><li>Smoke thật qua Gateway với dữ liệu <code>seed-admin-demo</code>: xem doanh thu, tải PDF tháng 9 (26 trang), kỳ rỗng báo MSG122, broadcast BY_PLAN=PRO 160 người nhận → SENT.</li><li>Migration <code>2026-10-04-admin-notifications-reports.sql</code>: chạy 2 lần trên DB test, backup <code>.tmp/brandhub-before-notifications-20261004.dump</code>, chạy 2 lần trên DB dev, 0 lỗi.</li></ul><p>Giới hạn còn lại: nhãn PDF song ngữ Việt/Anh cố định, chưa theo ngôn ngữ người xuất; tối đa 5.000 dòng chi tiết mỗi bảng.</p>',19)])])}const f=e(n,[["render",l]]);export{p as __pageData,f as default};
